insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-routine-yields-730-to-plain-s731','decision','The routine yields 730 to Sam''s plain session and takes S731','S731 conductor: the CPL Queue routine''s 10:12Z firing declared S730 at 11:05Z (#3823). Sam''s plain session SkyDunlin took S730 as handoff 730 named it (#3824, 11:19Z), so the declaration moved to S731 and writes handoff 732, leaving 731 to SkyDunlin (d-routine-takes-next-free-number-s713). A routine firing follows 732; a plain session follows 731.',array['conductor','routine','handoffs','numbering'],'proposed','docs/session_732_handoff.md',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('d-lever-dispatches-paid-reads-in-words-s731','decision','The lever worker dispatched paid reads on its own branch, in words','S731 conductor: to save its own context, the conductor let the lever worker dispatch paid reads on claude/s730-lever with only=, at most $5 a college and $15 in all on the estimate, beside the free steps S727 lifted in words (d-workers-dispatch-loads-in-words-s727). Applies stayed the conductor''s. The reads cost $0.23: West Valley $0.15, Allan Hancock $0.08.',array['conductor','workers','reads','spend'],'proposed','#3827',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('d-elumen-read-before-reader-s731','decision','The eLumen paid read went before its second reader','S731 conductor: Antelope Valley''s paid read (only= the 38 and 43150, force= the 38) was dispatched on claude/s730-elumen2 before its Sonnet second reader, since a read files to the branch only; the reader gated the load and the reread. Read 45612549421 ($2.76), load 45616752363, reread 45616970396.',array['program-requirements','elumen','antelope-valley','conductor'],'proposed','claude/s730-elumen2',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('d-display-merged-without-main-update-s731','decision','The display PR merged without a final update from main','S731 conductor: #3825, display build 2c8507c058b1 (18,724 records), merged at 11:44Z as 9a5deb35 without a final update from main, which had moved only by Sam''s plain session''s #3824, touching none of its files.',array['conductor','merge','display','program-requirements'],'proposed','#3825',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('d-waived-course-counted-keeps-50-s731','decision','waived_course_counted keeps a confidence of 50','S731 conductor, on s730b''s Opus reader: the new kind waived_course_counted (Saddleback 04069 and 22874, DR 100 exempt after high-school drafting; 41673 and 41674, CUL 171 waived for ServSafe) keeps confidence 50, since the figure closes only for a student who holds the waiver. Plan s730b, migrate 45609196483.',array['program-requirements','saddleback','named-gaps','confidence'],'proposed','#3830 (plan s730b)',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('d-lbcc-42970-no-units-read-or-hold-s731','decision','Long Beach City 42970 is held: no_units_read refused it','S731 conductor, on s731c''s round 1: 42970 had been filed under no_units_printed, a kind switched off since its self-recall failed. no_units_read''s own check refused it too, so 42970 is held with S681''s reason and s731c applied 12 rows (migrate 45612147342).',array['program-requirements','long-beach-city','named-gaps','held'],'proposed','#3830 (plan s731c)',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('d-multi-run-load-history-proves-run-s731c','decision','A load that held several runs proves each row''s run from history','S731, the Long Beach City worker''s call, confirmed by its second reader: where a load held two or three runs, each row''s run is proved from its record file''s commit history on main before the plan names it. Plan s731c, migrate 45612147342.',array['program-requirements','long-beach-city','receipts','rule-10'],'proposed','#3830 (plan s731c)',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('d-porterville-06773-keeps-s721c-gap-s731','decision','Porterville 06773 keeps s721c''s gap','S731 conductor: 06773''s read starts mid-page with no heading, so it left plan s731p (7 rows, migrate 45627220481) and stays collected with s721c''s gap, held by NG.GAP_HELD so a reconcile honors it. Round 2 found a reconcile still files fresh arithmetic beside the gap (f-porterville-06773-flips-on-reconcile-s731).',array['program-requirements','porterville','pooled','held'],'proposed','claude/s731-pooled (plan s731p)',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('p-worker-push-proved-by-ls-remote-s731','pitfall','A worker''s push counts only once git ls-remote shows it','S731: the elumen2 worker reported a push the remote did not hold (commit 0665e817), and the conductor dispatched Antelope Valley''s read 45603949086 on the stale head; it stopped at its price step, nothing spent. Briefs now ask for git ls-remote proof of a push, and the conductor reads the branch head before a dispatch.',array['conductor','workers','git','dispatch'],'proposed','docs/session_732_handoff.md',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('p-test-asserts-other-pr-absent-recurs-s731','pitfall','A test asserted another branch''s change absent, twice','S731: p-test-asserts-other-pr-absent-s721 recurred twice. s730b''s test asserted the seven repeat holds still fail, which the repeat branch changes; it now accepts either state. S703''s lists-past-figure test pinned Long Beach City 41220, which s731c moved, and failed lints (4) on #3830; land pinned 41220''s two states.',array['tests','program-requirements','ci','land'],'proposed','#3830',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('p-pooled-change-opus-reader-recall-s731','procedure','A scorer change gets an Opus reader and a statewide self-recall','S731: the pooled reading''s change behind POOLED_S731 got an Opus reader and a self-recall over all 18,962 records (18 read differently, none from passing to failing). Round 1 still found the CONTINUED-heading join went by position alone: 26 joins, 4 right, 22 wrong, which the recall did not count. The join now needs the first stem word to match.',array['program-requirements','pooled','self-recall','review'],'proposed','claude/s731-pooled; docs/kb-notes/methodology-a-self-check-must-see-what-the-rule-writes.md',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('f-porterville-06773-flips-on-reconcile-s731','risk','A Porterville reconcile would count 06773 passing','S731, s731p round 2 MAJOR, sent on, not fixed: under POOLED_S731 a Porterville reconcile keeps 06773''s gap but files the fresh arithmetic (18 equal to 18), so the census and the tab count it passing. Before any Porterville reconcile, keep the filed arithmetic for a GAP_HELD record (kb/_program_requirements_college.py, about line 7884), with a test that 06773 still fails.',array['program-requirements','porterville','pooled','reconcile'],'proposed','claude/s731-pooled (plan s731p)',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('f-continued-heading-list-b-joins-s731','fact','LIST A then LIST B CONTINUED still joins','S731, s731p round 2: after the stem-word fix, a heading "LIST A" followed by "LIST B CONTINUED" still joins, and general education and list-size sentences still fire the new pooled phrasings. No committed record has either shape; the night''s one follow-up tightens both.',array['program-requirements','pooled','scorer','follow-up'],'proposed','claude/s731-pooled (plan s731p)',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('f-waiver-shape-misses-six-s731','fact','The waiver shape misses six records worded otherwise','S731, s730b''s Opus reader: waived_course_counted''s shape misses six records whose waiver is worded otherwise: Saddleback 42644, 19551 and 22933; Orange Coast 42331; Madera 39862; Reedley 18957. For the night''s one follow-up.',array['program-requirements','named-gaps','saddleback','follow-up'],'proposed','#3830 (plan s730b)',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('f-green-read-files-only-preview-s731','fact','A read that held a partial capture ends green, filing only its preview','S731: West Valley''s S727 read 45574056664 restaged capture 43142245126 (2026-11-12), which predates page counting, so the price step held it as partial, skipped extraction, filed only capture_preview.json and ended green; load 45575119022 re-posted 133 rows already live. A fresh read fixed it. The read should fail or say so.',array['program-requirements','west-valley','reads','ci'],'proposed','#3827',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('f-follow-up-minors-s731','fact','Two minors for the night''s one follow-up','S731: the pile SQL guards abort through a ::int cast error, a cryptic message (s730a''s reader); js-tests.yml''s Long Beach City step comment says 10 named gaps and 3 held where the receipt says 9 and 4. Both go to the night''s one follow-up PR.',array['program-requirements','tests','follow-up'],'proposed','#3830',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('d-saddleback-reconcile-before-reader-s731','decision','Saddleback''s free reconcile went before its second reader','S731, the Saddleback worker''s dispatch, recorded by the conductor: reconcile 45606980427 (extract=0, filing to claude/s731-saddleback-repeat only) ran before a reader saw its block_sum change to shared reconcile code. The Opus reader (REREAD: statewide only the seven differ over 18,962 records) gated reread 45632688186, which replaced the seven, all passing.',array['program-requirements','saddleback','reconcile','conductor'],'proposed','claude/s731-saddleback-repeat',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('f-saddleback-repeat-window-s731','fact','Saddleback''s repeat steps'' window can bind a code the words do not name','S731, the Saddleback repeat branch''s Opus reader (minor): the repeat steps'' [\s\S]{0,200}? window can bind a course code the words do not name. Before Saddleback''s next read, put units:?\s*2(?:\.0+)?\s* before the code, drop the second step and rerun the recall. Its other minor: a commons_data conflict at the branch''s land.',array['program-requirements','saddleback','reconcile','follow-up'],'proposed','claude/s731-saddleback-repeat',null,null,'SkyFrigatebird (S731)','2026-11-25'),
('m-collection-s731','milestone','S731''s collection: 83 records live by 14:19Z','S731 (2026-11-25; the queue from 10:55Z on Sam''s word, "You should be clear to go"): 83 records collected and live: piles LATTC 6, Saddleback 8, LBCC 12; pooled 7; eLumen 40 (1 new, 39 own-page rereads); lever 3; Saddleback repeat 7. 3 named gaps, no record. Census after display 2c8507c058b1: 15,562 of 20,282 pass. Paid reads $3.11.',array['program-requirements','collection','milestone'],'proposed','#3825; #3830; #3827; claude/s731-saddleback-repeat; docs/session_732_handoff.md',null,null,'SkyFrigatebird (S731)','2026-11-25')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
